import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.Bqa2y7hU.js";const g=JSON.parse('{"title":"ABI 与兼容规则","description":"当前 ABI 版本、稳定性承诺、加载协商的三条规则、不兼容时的提示文案，以及什么时候必须重新编译插件。","frontmatter":{"title":"ABI 与兼容规则","description":"当前 ABI 版本、稳定性承诺、加载协商的三条规则、不兼容时的提示文案，以及什么时候必须重新编译插件。"},"headers":[],"relativePath":"plugin-dev/abi.md","filePath":"plugin-dev/abi.md","lastUpdated":1789486865000}'),r={name:"plugin-dev/abi.md"};function i(s,t,n,c,h,l){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="abi-与兼容规则" tabindex="-1">ABI 与兼容规则 <a class="header-anchor" href="#abi-与兼容规则" aria-label="Permalink to &quot;ABI 与兼容规则&quot;">​</a></h1><p>插件和框架之间靠一套 <strong>C ABI（应用二进制接口）</strong> 通信：插件导出固定名字的 C 函数，框架 <code>dlopen</code> 后按名字取符号。这页讲清楚这套接口的版本规则——<strong>什么时候你的插件能加载，什么时候会被拒绝，什么时候必须重新编译</strong>。</p><h2 id="当前版本" tabindex="-1">当前版本 <a class="header-anchor" href="#当前版本" aria-label="Permalink to &quot;当前版本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>ABI major</td><td><code>1</code></td></tr><tr><td>ABI minor</td><td><code>5</code></td></tr><tr><td>版本字符串</td><td><code>1.6</code></td></tr><tr><td>版本宏</td><td><code>BOT_ABI_VERSION_MAJOR</code> / <code>BOT_ABI_VERSION_MINOR</code></td></tr><tr><td>打包版本号</td><td><code>BOT_ABI_VERSION</code>（高 16 位 major、低 16 位 minor）</td></tr><tr><td>拆分宏</td><td><code>BOT_ABI_MAJOR_OF(v)</code> / <code>BOT_ABI_MINOR_OF(v)</code></td></tr></tbody></table><p>插件通过 <code>bot_plugin_abi_version()</code> 返回自己的 ABI 版本。用注册宏时这行是自动展开的：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;C&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint32_t</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bot_plugin_abi_version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BOT_ABI_VERSION; }</span></span></code></pre></div><p>所以<strong>插件声明的版本 = 编译它时所用 SDK 的版本</strong>。框架在 <code>bot_plugin_init</code> 时会把 <code>BotHostApi</code> 传给你，表头的 <code>abi_major</code> / <code>abi_minor</code> 就是框架自己的版本，插件可以据此判断宿主能力。</p><h2 id="稳定性承诺" tabindex="-1">稳定性承诺 <a class="header-anchor" href="#稳定性承诺" aria-label="Permalink to &quot;稳定性承诺&quot;">​</a></h2><p>v1 发布后，<code>bot_plugin.h</code> 里的这套合同遵循「<strong>只增不改</strong>」：</p><table tabindex="0"><thead><tr><th>对象</th><th>允许</th><th>禁止</th></tr></thead><tbody><tr><td>函数</td><td>追加新符号</td><td>改签名、改语义、删除</td></tr><tr><td>结构体</td><td>在<strong>尾部</strong>追加字段</td><td>重排字段、删除字段、改字段类型、改字段含义</td></tr><tr><td>事件类型枚举</td><td>尾部追加新枚举值</td><td>改已有值的编号</td></tr><tr><td>版本号</td><td>新增可选回调符号 / 尾部加字段 = <strong>minor++</strong></td><td>破坏性改动 = <strong>major++</strong></td></tr></tbody></table><p>对插件作者的实际含义：<strong>旧插件在新框架上永远能加载</strong>（旧插件不会去读它不认识的新字段），但<strong>新插件在旧框架上可能不成立</strong>（它依赖的新字段在旧框架的结构体里根本不存在）。这就是下面协商规则的由来。</p><h2 id="加载协商的三条规则" tabindex="-1">加载协商的三条规则 <a class="header-anchor" href="#加载协商的三条规则" aria-label="Permalink to &quot;加载协商的三条规则&quot;">​</a></h2><p>框架拿到插件声明的版本 <code>v</code>（<code>p_maj</code> = major，<code>p_min</code> = minor）后：</p><table tabindex="0"><thead><tr><th>#</th><th>规则</th><th>结果</th></tr></thead><tbody><tr><td>1</td><td>插件 major <strong>必须等于</strong>框架 major</td><td>不等 → <strong>拒绝加载</strong></td></tr><tr><td>2</td><td>插件 minor <strong>大于</strong>框架 minor</td><td><strong>拒绝加载</strong>（插件依赖更新的宿主 API 尾部字段，加载会读到越界内存）</td></tr><tr><td>3</td><td>插件 minor <strong>小于等于</strong>框架 minor</td><td><strong>兼容</strong>（旧插件不引用新字段，天然向后兼容）</td></tr></tbody></table><p>用一张表看几个例子（假设框架是 1.6）：</p><table tabindex="0"><thead><tr><th>插件版本</th><th>结果</th><th>原因</th></tr></thead><tbody><tr><td>1.0</td><td>加载</td><td>minor 更低，兼容</td></tr><tr><td>1.3</td><td>加载</td><td>兼容</td></tr><tr><td>1.6</td><td>加载</td><td>完全一致</td></tr><tr><td>1.6</td><td>拒绝</td><td>插件比框架新（规则 2）</td></tr><tr><td>2.0</td><td>拒绝</td><td>major 不一致（规则 1）</td></tr></tbody></table><h2 id="不兼容时的提示文案" tabindex="-1">不兼容时的提示文案 <a class="header-anchor" href="#不兼容时的提示文案" aria-label="Permalink to &quot;不兼容时的提示文案&quot;">​</a></h2><p>major 不一致时，日志里会出现这样一条（路径是你的实际插件路径）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/mybot/mybot.so: ABI 不兼容——插件 v2.0 要求 major=2，但框架为 1.6 (major=1)；需用与框架同版本的 SDK 重新编译插件</span></span></code></pre></div><p>插件 minor 比框架新时：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/mybot/mybot.so: 插件 v1.6 需要更新的宿主 API，但框架为 1.5；请升级框架或改用 v1.5 SDK 编译</span></span></code></pre></div><p>处理方式很直接：</p><ul><li>第一种情况：用与框架同 major 的 SDK <strong>重新编译</strong>插件；</li><li>第二种情况：<strong>升级框架</strong>到不低于插件 minor 的版本，或用更低版本的 SDK 重新编译插件。</li></ul><p>其余加载期错误（缺符号、初始化失败）见 <a href="/RuaBot.Doc/plugin-dev/debugging">调试与排错</a>。</p><h2 id="版本变更对照表" tabindex="-1">版本变更对照表 <a class="header-anchor" href="#版本变更对照表" aria-label="Permalink to &quot;版本变更对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>新增内容</th><th>对插件的影响</th></tr></thead><tbody><tr><td><code>1.0</code></td><td>基础合同：注册与生命周期符号、消息/通知/请求回调、三个拦截器、Host API 的发送/KV/Blob/设置/日志/指令/能力发现与调用</td><td>最小可用集合</td></tr><tr><td>早于 <code>1.3</code></td><td><code>http_get</code> + <code>free</code>（插件出站 HTTP GET）</td><td>用 <code>bot::http_get</code> 拉取外部数据</td></tr><tr><td><code>1.3</code></td><td>插件 Web 面板：<code>BotPluginMeta</code> 尾部追加 <code>web_entry</code> / <code>web_title</code>、<code>BotWebRequest</code> / <code>BotWebResponse</code>、<code>bot_plugin_web_route</code> 回调、<code>setting_set</code>（写当前插件+机器人配置）</td><td>插件可自带网页面板并持久化配置</td></tr><tr><td><code>1.4</code></td><td>面板事件推送：<code>panel_push</code></td><td>面板可以实时收到插件推的事件</td></tr><tr><td><code>1.5</code></td><td>任意 method 出站 HTTP：<code>http_request</code>（GET/POST/PUT/PATCH/DELETE/HEAD/OPTIONS）</td><td>插件可调用任意外部 API</td></tr><tr><td><code>1.6</code></td><td>按 bot 显式读写设置：<code>setting_get_for</code> / <code>setting_set_for</code></td><td><strong>后台线程、停机钩子里也能落盘</strong>（1.5 及以前只有依赖上下文的版本，那里写会被静默忽略）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">生成面板元数据要 1.3 及以上的 SDK</p><p><code>web_entry</code> / <code>web_title</code> 是 1.3 追加到结构体尾部的字段。用更早的 SDK 编译出的插件（minor &lt; 3）框架不会去读这两个字段，面板自然也不会出现——写面板请用当前 SDK。</p></div><h2 id="什么时候需要重新编译插件" tabindex="-1">什么时候需要重新编译插件 <a class="header-anchor" href="#什么时候需要重新编译插件" aria-label="Permalink to &quot;什么时候需要重新编译插件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>要不要重编</th></tr></thead><tbody><tr><td>框架升级了 <strong>major</strong>（例如 1.x → 2.0）</td><td><strong>必须</strong>，否则拒绝加载</td></tr><tr><td>框架升级了 minor（例如 1.6 → 1.7）</td><td>不用；旧插件继续加载，只是用不到新能力</td></tr><tr><td>想使用比编译时更新的 minor 接口（例如 1.6 的 <code>setting_set_for</code>）</td><td><strong>必须</strong>，需要用 ≥ 该版本的 SDK 重编</td></tr><tr><td>换了操作系统 / CPU 架构（Linux x86_64 → ARM）</td><td><strong>必须</strong>，动态库是平台相关的</td></tr><tr><td>只改了插件自己的代码</td><td>重新编译，这是当然的</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/plugin-dev/lifecycle">生命周期回调</a>：注册宏展开出的符号分别在什么时候被调用</li><li><a href="/RuaBot.Doc/reference/host-api">Host API</a>：每个接口所属的 ABI 版本</li><li><a href="/RuaBot.Doc/plugin-dev/debugging">调试与排错</a>：加载失败时怎么定位</li></ul>',31)])])}const b=d(r,[["render",i]]);export{g as __pageData,b as default};
